const d = msg.payload;

const score_niveau = Math.min(100, (d.niveau_eau / d.seuil_danger) * 60);
const score_pluie  = Math.min(40,  (d.pluviometrie / 20) * 40);
const risque = Math.round(score_niveau + score_pluie);

d.risque_inondation = risque;
d.classe_risque = risque >= 80 ? 'CRITIQUE' :
                  risque >= 60 ? 'ÉLEVÉ'    :
                  risque >= 40 ? 'MODÉRÉ'   : 'FAIBLE';

msg.payload = d;
return msg;

const d = msg.payload;
msg.topic   = 'DANGER INONDATION — ' + d.zone_nom;
msg.payload = '🚨 DANGER: ' + d.zone_nom + '\nNiveau: ' + d.niveau_eau + 'm\nRivière: ' + d.riviere + '\nTimestamp: ' + d.timestamp;
return msg;

const d = msg.payload;
